def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    orth = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    diag = [(dy, dx) for dy in (-1, 0, 1) for dx in (-1, 0, 1)
            if dy or dx]

    # Find all zero regions, recording which touch the grid edge.
    seen = [[False] * w for _ in range(h)]
    regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            exterior = False
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    exterior = True
                for dy, dx in orth:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and not seen[ny][nx]:
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            regions.append((cells, exterior))

    # A non-exterior zero region identifies a 1-object with an interior.
    hole_cells = set()
    eligible_ones = set()
    for cells, exterior in regions:
        if exterior:
            continue
        hole_cells.update(cells)
        for r, c in cells:
            for dy, dx in orth:
                nr, nc = r + dy, c + dx
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                    eligible_ones.add((nr, nc))

    if not eligible_ones:
        return out

    # Expand from the bordering 1s to their full orthogonally connected objects.
    objects = set(eligible_ones)
    stack = list(eligible_ones)
    while stack:
        r, c = stack.pop()
        for dy, dx in orth:
            nr, nc = r + dy, c + dx
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1
                    and (nr, nc) not in objects):
                objects.add((nr, nc))
                stack.append((nr, nc))

    # Color the inner contour (including diagonal adjacency) and outer outline.
    for r, c in hole_cells:
        if any((r + dy, c + dx) in objects for dy, dx in diag):
            out[r][c] = 3

    for r, c in objects:
        for dy, dx in diag:
            nr, nc = r + dy, c + dx
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and (nr, nc) not in hole_cells):
                out[nr][nc] = 2

    return out
